from pathlib import Path
import json,base64,hashlib
p=Path(__file__).resolve().parent;r=p.parents[1];o=p/'north-unload-rise-between-v317';m=json.loads((o/'bare-review-manifest.json').read_bytes());states=m['states'][:2];data={s['id']:dict(images=['data:image/png;base64,'+base64.b64encode((r/f[6:]).read_bytes()).decode() for f in s['frameFiles']],clocks=s['frameDurationsMs']) for s in states}
html='''<!doctype html><meta charset="utf-8"><title>James unloading playback review</title><style>body{background:#303b40;color:#eee;font:16px sans-serif;margin:16px}button,select,input{margin:8px}h1{font-size:22px}h2{font-size:18px}.row{display:flex;align-items:end;gap:35px;height:200px}img{object-fit:contain}</style><h1>James unloading — provisional</h1><p>Original and revised sources follow their own clocks. Both last 520 ms. Helmet and integration pending.</p><button id="play">Replay</button><button id="pause">Pause</button><label>Speed <select id="speed"><option value="1">Normal</option><option value="0.25">Quarter speed</option><option value="0.125">Eighth speed</option></select></label><label>Loop <input id="loop" type="checkbox"></label><label>Time <input id="seek" type="range" min="0" max="519" value="0"></label><strong id="status"></strong><h2>Original six poses</h2><div class="row" id="original"></div><h2>Revised seven poses</h2><div class="row" id="candidate"></div><p>Standing ruler: 148, 82, 54 and 27 pixels. Replay resets are viewer resets, not an authored loop.</p><script>const data=DATA;const sizes=[148,82,54,27],imgs={};let elapsed=0,running=false,last=0;for(const key of ['original','candidate'])imgs[key]=sizes.map(n=>{const im=document.createElement('img');im.width=256*n/148;im.height=256*n/148;document.getElementById(key).append(im);return im});function index(key,t){let acc=0;for(let i=0;i<data[key].clocks.length;i++){acc+=data[key].clocks[i];if(t<acc)return i}return data[key].clocks.length-1}function show(){const a=index('original',elapsed),b=index('candidate',elapsed);for(const key of Object.keys(imgs))for(const im of imgs[key])im.src=data[key].images[index(key,elapsed)];document.getElementById('seek').value=Math.floor(elapsed);document.getElementById('status').textContent=`${Math.floor(elapsed)} ms · original ${a}/5 · candidate ${b}/6 · ${running?'playing':'paused'}`}function tick(t){if(running){elapsed+=(t-last)*Number(document.getElementById('speed').value);if(elapsed>=520){if(document.getElementById('loop').checked)elapsed%=520;else{elapsed=519.999;running=false}}show()}last=t;requestAnimationFrame(tick)}document.getElementById('play').onclick=()=>{elapsed=0;running=true;last=performance.now();show()};document.getElementById('pause').onclick=()=>{running=false;show()};document.getElementById('seek').oninput=e=>{elapsed=Number(e.target.value);running=false;show()};show();requestAnimationFrame(tick);</script>'''.replace('DATA',json.dumps(data))
(o/'playback-review.html').write_text(html,encoding='utf-8');sources={f[6:]:hashlib.sha256((r/f[6:]).read_bytes()).hexdigest() for s in states for f in s['frameFiles']};(o/'playback-inputs.json').write_text(json.dumps(dict(sources=sources,htmlSha256=hashlib.sha256((o/'playback-review.html').read_bytes()).hexdigest(),originalClocks=states[0]['frameDurationsMs'],candidateClocks=states[1]['frameDurationsMs'],normalChanged=False),indent=2)+'\n',encoding='utf-8');print('Built independent-clock comparison:13 source slots,520ms each.')
